INSERT INTO field_def(field_id,version,display_name,definition,value_domain,unit,granularity,event_time_meaning,applicable_districts,sensitivity,valid_from,status,namespace) VALUES
 ('std.li_iso_level',1,'锂电隔离等级（标准四级）','锂电池储能/充电场所的防火隔离与分隔风险等级，统一序次 1=常规隔离 / 2=加强关注 / 3=限期整改 / 4=重大立即管控；由现场、复查、盲审照片与量测反演统一标准化','{"type":"ordinal","values":[1,2,3,4],"labels":["常规隔离","加强关注","限期整改","重大管控"]}','级','场所-多次测量','每次检查/复查/盲审/量测时刻','{}','INTERNAL','2026-01-15','ACTIVE','CITY'),
 ('std.li_photo_grade',1,'锂电隔离照片快评等级','仅凭现场照片快速判读的隔离等级（采集快、适应新场景），但受光照/遮挡/距离与检查员差异影响大；一致性闸门未通过前只可登记填报，不得驱动跨区排名','{"type":"ordinal","values":[1,2,3,4]}','级','单次照片判读','照片盲审时刻','{}','INTERNAL','2026-02-01','ACTIVE','CITY')
